<script setup>
import {ref,computed,onUnmounted} from 'vue';import BaseModal from '../components/BaseModal.vue';import AccessMatrix from '../components/AccessMatrix.vue';import {state,api,useResource,changed,notify,ask} from '../lib/workspace';
import {can,allowedApi,writable} from '../lib/workspace';import {dateTime} from '../lib/format';
const show=ref(false),form=ref({}),error=ref(''),busy=ref(false),effective=ref(null),effectiveCid=ref(''),onlyAllowed=ref(false);let baseline='';
const {data,error:loadError}=useResource(async()=>{const [users,groups,catalog,audit]=await Promise.all([api('/users'),api('/groups'),api('/permissions/catalog'),api('/access-audit')]);return {users,groups,catalog,audit};},{users:[],groups:[],catalog:null,audit:[]});
function open(u=null){form.value=u?JSON.parse(JSON.stringify(u)):{username:'',password:'',role:'custom',active:true,company_ids:[],group_ids:[],company_access:[],permissions:[]};for(const id of form.value.company_ids)if(!form.value.company_access.some(p=>p.company_id===id))form.value.company_access.push({company_id:id,effect:'allow'});form.value.company_ids=[];form.value.password='';baseline=JSON.stringify(form.value);error.value='';show.value=true;state.editor={name:'Permissões de usuário'};}
async function close(){if(busy.value)return;if(baseline!==JSON.stringify(form.value)&&!await ask({title:'Descartar alterações?',message:'Os acessos ainda não foram salvos.',confirmLabel:'Descartar'}))return;show.value=false;state.editor=null;}
function companyRule(cid){return form.value.company_access.find(p=>p.company_id===cid)?.effect||'';}
function setCompany(cid,effect){form.value.company_access=form.value.company_access.filter(p=>p.company_id!==cid);if(effect)form.value.company_access.push({company_id:cid,effect});}
async function save(){busy.value=true;error.value='';try{await api('/users'+(form.value.id?'/'+form.value.id:''),{method:form.value.id?'PUT':'POST',body:form.value});show.value=false;state.editor=null;changed();notify('Acessos salvos. Sessões anteriores deste usuário foram encerradas.');}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function inspect(u){try{effective.value=await api(`/users/${u.id}/effective`);effectiveCid.value=effective.value.companies.find(c=>c.allowed)?.id||effective.value.companies[0]?.id||'';}catch(e){notify(e.message,'error');}}
const effectiveCompany=computed(()=>effective.value?.companies.find(c=>c.id===Number(effectiveCid.value)));
onUnmounted(()=>{if(show.value)state.editor=null;});
</script>
<template><div class="view"><header class="view-heading"><div><div class="eyebrow">SISTEMA · CONTROLE DE ACESSO</div><h1>Usuários e acessos</h1><p>Empresas, grupos, exceções individuais e permissões efetivas.</p></div><button class="button primary" @click="open()">Novo usuário</button></header><p v-if="loadError" class="message error">{{loadError}}</p><section class="panel table-scroll"><table><thead><tr><th>Usuário</th><th>Perfil</th><th>Situação</th><th>Grupos</th><th>Ações</th></tr></thead><tbody><tr v-for="u in data.users" :key="u.id"><td>{{u.username}}</td><td>{{u.role==='admin'?'Administrador':'Permissões configuradas'}}</td><td>{{u.active?'Ativo':'Desativado'}}</td><td>{{u.group_ids.map(id=>data.groups.find(g=>g.id===id)?.name||id).join(', ')||'Sem grupo'}}</td><td><div class="actions"><button class="button small" @click="open(u)">Editar acesso</button><button class="button small outline" @click="inspect(u)">Permissões efetivas</button></div></td></tr></tbody></table></section>
<section class="panel"><div class="panel-heading"><h2>Auditoria de usuários e grupos</h2><small>Últimas 200 alterações</small></div><div class="table-scroll"><table><thead><tr><th>Data</th><th>Responsável</th><th>Cadastro</th><th>Ação</th><th>Alteração</th></tr></thead><tbody><tr v-for="e in data.audit" :key="e.id"><td>{{dateTime(e.created_at)}}</td><td>{{e.actor}}</td><td>{{e.entity==='user'?'Usuário':'Grupo'}} #{{e.entity_id}}</td><td>{{e.action==='create'?'Inclusão':'Edição'}}</td><td><details><summary>Ver concessões e restrições</summary><pre>{{JSON.stringify({antes:e.details.before,depois:e.details.after,senha_alterada:e.details.password_changed},null,2)}}</pre></details></td></tr></tbody></table></div></section>
<BaseModal v-if="show" title="Acesso do usuário" wide @close="close"><p v-if="error" class="message error" role="alert">{{error}}</p><form id="user-form" @submit.prevent="save"><div class="form-grid"><label>Usuário *<input v-model="form.username" required/></label><label>{{form.id?'Nova senha (opcional)':'Senha *'}}<input v-model="form.password" type="password" autocomplete="new-password" minlength="12" :required="!form.id"/></label><label>Perfil<select v-model="form.role"><option value="custom">Permissões por empresa</option><option v-if="['viewer','operator'].includes(form.role)" :value="form.role">Legado · permissões preservadas</option><option value="admin">Administrador global</option></select></label><label>Situação<select v-model="form.active"><option :value="true">Ativo</option><option :value="false">Desativado</option></select></label></div><p v-if="form.role==='admin'" class="message warning">O administrador global tem todas as empresas e ações, independentemente dos grupos ou exceções.</p><template v-else><fieldset><legend>Grupos</legend><label v-for="g in data.groups" :key="g.id" class="inline-choice"><input v-model="form.group_ids" type="checkbox" :value="g.id"/>{{g.name}} {{g.active?'':'(desativado)'}}</label><p v-if="!data.groups.length">Sem grupos cadastrados. É possível conceder acessos diretamente abaixo.</p></fieldset><fieldset><legend>Acesso individual às empresas</legend><p>Herdar depende de grupo ativo. Bloquear impede toda operação nessa empresa, mesmo com permissão de rotina.</p><label v-for="c in state.companies" :key="c.id" class="company-access-row"><span>{{c.code}} · {{c.name}}</span><select :value="companyRule(c.id)" @change="setCompany(c.id,$event.target.value)" :aria-label="`Acesso à empresa ${c.code}`"><option value="">Herdar dos grupos</option><option value="allow">Conceder diretamente</option><option value="deny">Bloquear empresa</option></select></label></fieldset><AccessMatrix v-if="data.catalog" v-model="form.permissions" :catalog="data.catalog" individual/></template></form><template #footer><button class="button" @click="close" :disabled="busy">Cancelar</button><button class="button primary" form="user-form" :disabled="busy">Salvar acesso</button></template></BaseModal>
<BaseModal v-if="effective" :title="'Permissões efetivas · '+effective.user.username" wide @close="effective=null"><p class="message subtle">Administrador → bloqueio individual da empresa → empresa concedida → negação individual → concessão individual → negação de grupo → concessão de grupo → negado por padrão.</p><div class="form-grid"><label>Empresa<select v-model="effectiveCid"><option v-for="c in effective.companies" :key="c.id" :value="c.id">{{c.code}} · {{c.name}} · {{c.allowed?'acessível':'sem acesso'}}</option></select></label><label class="check-label"><input v-model="onlyAllowed" type="checkbox"/>Mostrar somente ações permitidas</label></div><template v-if="effectiveCompany"><p><strong>{{effectiveCompany.allowed?'Empresa acessível':'Empresa bloqueada'}}</strong> · {{effectiveCompany.origins.join('; ')}}</p><div class="table-scroll"><table><thead><tr><th>Módulo / rotina</th><th>Ação</th><th>Resultado</th><th>Origem e exceções</th></tr></thead><tbody><template v-for="r in effectiveCompany.routines" :key="r.id"><tr v-for="(d,a) in r.actions" v-show="!onlyAllowed||d.allowed" :key="r.id+a"><td>{{data.catalog?.modules[r.module]}} · {{r.name}}</td><td>{{data.catalog?.actions[a]}}</td><td><span class="badge" :class="d.allowed?'success':'warning'">{{d.allowed?'Permitido':'Negado'}}</span></td><td>{{d.origin}}<small class="cell-secondary">{{d.sources.join('; ')}}</small></td></tr></template></tbody></table></div></template><template #footer><button class="button" @click="effective=null">Fechar</button></template></BaseModal></div></template>
<style scoped>.company-access-row{display:grid;grid-template-columns:minmax(0,1fr) 210px;gap:10px;align-items:center;margin:8px 0}pre{max-width:560px;max-height:250px;overflow:auto;font-size:11px}@media(max-width:600px){.company-access-row{grid-template-columns:1fr}}</style>
